package formal

// Arithmetic in GF(2^8).
//
// The field is generated by the primitive polynomial
//
//	x^8 + x^4 + x^3 + x^2 + 1
//
// (0x11d) with 2 as a primitive element.  The tables are built once at
// package initialisation, so every encoding is a pure deterministic function
// of its input.

const gfPrimitivePolynomial = 0x1d

var (
	gfExp [512]byte
	gfLog [256]byte
)

func init() {
	x := byte(1)
	for i := 0; i < 255; i++ {
		gfExp[i] = x
		gfLog[x] = byte(i)
		carry := x & 0x80
		x <<= 1
		if carry != 0 {
			x ^= gfPrimitivePolynomial
		}
	}
	for i := 255; i < len(gfExp); i++ {
		gfExp[i] = gfExp[i-255]
	}
}

// gfMul returns a*b in GF(2^8).
func gfMul(a, b byte) byte {
	if a == 0 || b == 0 {
		return 0
	}
	return gfExp[int(gfLog[a])+int(gfLog[b])]
}

// gfInv returns the multiplicative inverse of a.  It panics when a is zero;
// all callers establish that the value is non-zero first.
func gfInv(a byte) byte {
	if a == 0 {
		panic("formal: inverse of zero in GF(2^8)")
	}
	return gfExp[255-int(gfLog[a])]
}

// gfDiv returns a/b in GF(2^8).
func gfDiv(a, b byte) byte {
	if b == 0 {
		panic("formal: division by zero in GF(2^8)")
	}
	if a == 0 {
		return 0
	}
	return gfExp[int(gfLog[a])+255-int(gfLog[b])]
}

// gfPow returns a^n in GF(2^8).
func gfPow(a byte, n int) byte {
	if n == 0 {
		return 1
	}
	if a == 0 {
		return 0
	}
	return gfExp[(int(gfLog[a])*n)%255]
}

// gfMulAdd computes dst ^= src*coeff element-wise.
func gfMulAdd(dst, src []byte, coeff byte) {
	switch coeff {
	case 0:
		return
	case 1:
		for i := range src {
			dst[i] ^= src[i]
		}
	default:
		for i := range src {
			dst[i] ^= gfMul(src[i], coeff)
		}
	}
}
